func Prepare(ctx context.Context, request Request) (target.Prepared, error) {
	return prepare(ctx, request, os.RemoveAll)
}

func prepare(ctx context.Context, request Request, remove func(string) error) (prepared target.Prepared, retErr error) {
	profile := deterministicio.Default()
	spec := request.Target
	preparer := request.Preparer
	selectedAdapters := []deterministicio.BuildAdapter{}
	if preparer == nil {
		if err := os.MkdirAll(spec.PreparationRoot, 0o700); err != nil {
			return target.Prepared{}, &stageError{stage: StageAdapters, err: fmt.Errorf("create preparation root: %w", err)}
		}
		workspace, err := os.MkdirTemp(spec.PreparationRoot, ".adapter-work-")
		if err != nil {
			return target.Prepared{}, &stageError{stage: StageAdapters, err: fmt.Errorf("create deterministic I/O adapter workspace: %w", err)}
		}
		defer func() {
			if cleanupErr := remove(workspace); cleanupErr != nil {
				failure := &stageError{stage: StageCleanup, err: fmt.Errorf("remove deterministic I/O adapter workspace: %w", cleanupErr)}
				retErr = errors.Join(retErr, failure)
			}
		}()
		adapterSpec := spec
		adapterSpec.PreparationRoot = workspace
		spec, selectedAdapters, err = profile.PrepareTargetBuildAdapters(ctx, adapterSpec)
		if err != nil {
			return target.Prepared{}, &stageError{stage: StageAdapters, err: err}
		}
		spec.PreparationRoot = request.Target.PreparationRoot
		preparer = targetPreparer{}
	}
	var err error
	prepared, err = preparer.Prepare(ctx, spec)
	if err != nil {
		return target.Prepared{}, &stageError{stage: StageTarget, err: err}
	}
	prepared.Adapters = executionAdapters(selectedAdapters)
	if err := profile.ValidatePreparedTarget(spec, prepared, request.Environment); err != nil {
		return target.Prepared{}, &stageError{stage: StageValidation, err: err}
	}
	return prepared, nil
}

type targetPreparer struct{}

func (targetPreparer) Prepare(ctx context.Context, spec target.Spec) (target.Prepared, error) {
	return target.Prepare(ctx, spec)
}

func (profile Spec) ValidatePreparedTarget(spec target.Spec, prepared target.Prepared, environment []string) error {
	definition, err := profile.validated()
	if err != nil {
		return err
	}
	if spec.Kind != prepared.Kind || spec.Source != prepared.Source {
		return fmt.Errorf("deterministic I/O target identity does not match its build specification")
	}
	if len(prepared.Argv) == 0 || prepared.Argv[0] != "gomad3-target" || !equalStrings(spec.Args, prepared.Argv[1:]) {
		return fmt.Errorf("deterministic I/O target arguments do not match their build specification")
	}
	if prepared.GoVersion != definition.target.GoVersion || prepared.TargetGOOS != definition.target.GOOS || prepared.TargetGOARCH != definition.target.GOARCH {
		return fmt.Errorf("deterministic I/O requires Go %s on %s/%s; target was built with %s for %s/%s", definition.target.GoVersion, definition.target.GOOS, definition.target.GOARCH, prepared.GoVersion, prepared.TargetGOOS, prepared.TargetGOARCH)
	}
	adapters := make([]Adapter, len(prepared.Adapters))
	for index, adapter := range prepared.Adapters {
		adapters[index] = Adapter{Module: adapter.Module, Version: adapter.Version, Sum: adapter.Sum}
	}
	if err := profile.VerifyAdapters(adapters); err != nil {
		return fmt.Errorf("deterministic I/O target adapters: %w", err)
	}
	return nil
}

func (profile Spec) BootstrapFrame(prepared target.Prepared, runnerSHA256 string, seed uint64) ([]byte, error) {
	_, err := profile.validated()
	if err != nil {
		return nil, err
	}
	argv, err := canonicalJSON(prepared.Argv)
	if err != nil {
		return nil, fmt.Errorf("encode target argv identity: %w", err)
	}
	identity := profile.Identity()
	digests := []string{string(identity.InventorySHA256), string(identity.ImplementationSHA256), prepared.SHA256, runnerSHA256, string(hashBytes(argv))}
	wire := iowire.Bootstrap{Seed: seed}
	destinations := []*[sha256.Size]byte{&wire.InventoryHash, &wire.ImplementationHash, &wire.TargetHash, &wire.RunnerHash, &wire.ArgvHash}
	for index, value := range digests {
		decoded, decodeErr := parseSHA256(value)
		if decodeErr != nil {
			return nil, decodeErr
		}
		copy(destinations[index][:], decoded)
	}
	frame := iowire.EncodeBootstrap(wire)
	return frame[:], nil
}

func DecodeBootstrapFrame(frame []byte) (Bootstrap, error) {
	decoded, err := iowire.DecodeBootstrap(frame)
	if err != nil {
		return Bootstrap{}, fmt.Errorf("decode I/O profile bootstrap frame: %w", err)
	}
	digests := make([]string, 0, 5)
	for _, digest := range [][sha256.Size]byte{decoded.InventoryHash, decoded.ImplementationHash, decoded.TargetHash, decoded.RunnerHash, decoded.ArgvHash} {
		digests = append(digests, "sha256:"+hex.EncodeToString(digest[:]))
	}
	profile := Default()
	identity := Contract{Name: profile.Name(), InventorySHA256: Digest(digests[0]), ImplementationSHA256: Digest(digests[1])}
	if !profile.Matches(identity) {
		return Bootstrap{}, errors.New("I/O profile bootstrap frame identity mismatch")
	}
	return Bootstrap{
		Profile: identity.Name, InventorySHA256: identity.InventorySHA256, ImplementationSHA256: identity.ImplementationSHA256,
		TargetSHA256: digests[2], RunnerSHA256: digests[3], ArgvSHA256: Digest(digests[4]), Seed: decoded.Seed,
	}, nil
}

func TestCancellationIsAHostFailure(t *testing.T) {
	for _, strategy := range completionStrategies {
		t.Run(string(strategy), func(t *testing.T) {
			var config CampaignSpec
			var configDependencies executionDependencies
			if strategy == StrategySeed {
				config, configDependencies = testConfig(t, newFakePreparer(t), blockingExecutor{}, "1", PolicyAll, 1)
			} else {
				config, _, configDependencies = completionCampaign(t, strategy, CoverageNone, nil, nil)
				configDependencies.executor = blockingExecutor{}
			}
			ctx := cancelOnProgress(t, &config, func(progress CampaignEvent) bool { return progress.Running == 1 })
			config.TerminateGrace = 10 * time.Millisecond
			summary, err := exploreWith(ctx, config, configDependencies)
			if strategy != StrategySeed {
				observed := observeCompletion(t, summary, err)
				// The round returns while its candidate is still exiting, so the
				// candidate's partial state is not settled yet.
				observed.Partials = nil
				if want := (completionObservation{Reason: "cancelled", Cause: "context canceled"}); !reflect.DeepEqual(observed, want) {
					t.Fatalf("completion = %#v, want %#v", observed, want)
				}
				return
			}
			var hostError *HostError
			if !errors.As(err, &hostError) || hostError.Reason != "cancelled" || !errors.Is(err, context.Canceled) {
				t.Fatalf("exploreWith() error = %#v", err)
			}
			if summary.Failures != 0 || len(summary.Artifacts) != 0 {
				t.Fatalf("cancelled summary = %#v", summary)
			}
			plan, planErr := campaign.ReadResumePlan(summary.CampaignPath)
			if planErr != nil {
				t.Fatal(planErr)
			}
			if plan.Selection != "1" || plan.RunnerBuild != config.RunnerBuild || plan.Prepared.Target.SHA256 == "" {
				t.Fatalf("resume plan = %#v", plan)
			}
			partials, readErr := os.ReadDir(filepath.Join(summary.CampaignPath, ".partial"))
			if readErr != nil {
				t.Fatal(readErr)
			}
			if len(partials) != 3 {
				t.Fatalf("cancelled partials = %v, want campaign, executions, and target", partials)
			}
			if _, err := os.Stat(filepath.Join(summary.CampaignPath, ".partial", "campaign", "partial.json")); err != nil {
				t.Fatal(err)
			}
		})
	}
}

// A well-formed completion carries its World record, semantic probe and choice
// features into the execution evidence and the journal for fixed identities.

func TestReplayDoesNotStartTarget(t *testing.T) {
	type replayCase struct {
		name string
		// publish returns the artifact path and the result a started target
		// would report.
		publish    func(t *testing.T) (string, execution.Result)
		verifyOnly bool
		// wantVerified expects verification to succeed; otherwise replay fails.
		wantVerified bool
	}
	cases := []replayCase{
		{name: "verify only", publish: replayArtifact, verifyOnly: true, wantVerified: true},
		{name: "unavailable compatibility pack", verifyOnly: true, publish: func(t *testing.T) (string, execution.Result) {
			return publishReplayArtifactWithCompatibility(t, []record.CompatibilityPack{{
				ID: "unknown-pack", SHA256: record.HashBytes([]byte("unknown pack")),
			}})
		}},
		{name: "changed payload", publish: func(t *testing.T) (string, execution.Result) {
			artifactPath, expected := replayArtifact(t)
			if err := os.Chmod(filepath.Join(artifactPath, "stdout"), 0o600); err != nil {
				t.Fatal(err)
			}
			if err := os.WriteFile(filepath.Join(artifactPath, "stdout"), []byte("changed"), 0o600); err != nil {
				t.Fatal(err)
			}
			return artifactPath, expected
		}},
	}
	for _, damage := range []struct {
		name   string
		damage func(t *testing.T, artifactPath, entry string)
	}{
		{name: "altered", damage: func(t *testing.T, _, entry string) {
			file, err := os.OpenFile(entry, os.O_WRONLY, 0)
			if err != nil {
				t.Fatal(err)
			}
			if _, err := file.WriteAt([]byte("altered"), 0); err != nil {
				t.Fatal(err)
			}
			if err := file.Close(); err != nil {
				t.Fatal(err)
			}
		}},
		{name: "truncated", damage: func(t *testing.T, _, entry string) {
			info, err := os.Stat(entry)
			if err != nil {
				t.Fatal(err)
			}
			if err := os.Truncate(entry, info.Size()-1); err != nil {
				t.Fatal(err)
			}
		}},
		{name: "missing", damage: func(t *testing.T, artifactPath, _ string) {
			if err := os.Remove(filepath.Join(artifactPath, "target")); err != nil {
				t.Fatal(err)
			}
		}},
	} {
		for _, verifyOnly := range []bool{false, true} {
			cases = append(cases, replayCase{name: fmt.Sprintf("damaged shared target/%s/verify-only=%t", damage.name, verifyOnly), verifyOnly: verifyOnly, publish: func(t *testing.T) (string, execution.Result) {
				pool := artifact.TargetPool(t.TempDir())
				artifactPath, expected := publishReplayArtifactForTarget(t, nil, replayArtifactTarget{TargetPool: pool})
				entries, err := os.ReadDir(pool)
				if err != nil || len(entries) != 1 {
					t.Fatalf("pool entries = %v, %v", entries, err)
				}
				entry := filepath.Join(pool, entries[0].Name())
				if distinctFiles(t, []string{entry, filepath.Join(artifactPath, "target")}) != 1 {
					t.Fatal("published target does not share its pool entry")
				}
				damage.damage(t, artifactPath, entry)
				return artifactPath, expected
			}})
		}
	}
	for _, test := range cases {
		t.Run(test.name, func(t *testing.T) {
			artifactPath, expected := test.publish(t)
			executor := &fakeReplayExecutor{result: expected}
			result, err := replayWith(context.Background(), ReplaySpec{
				ArtifactPath: artifactPath, VerifyOnly: test.verifyOnly, ToolchainRoot: toolchainRoot(t), SupervisorCommand: []string{"unused"},
			}, executionDependencies{executor: executor},
			)
			if executor.calls != 0 || (err == nil) != test.wantVerified || test.wantVerified && (!result.Verified || result.Match) {
				t.Fatalf("replayWith() result = %#v, error = %v, calls = %d", result, err, executor.calls)
			}
		})
	}
}

func publishReplayArtifact(t *testing.T, connected *execution.Bundle) (string, execution.Result) {
	return publishReplayArtifactWithWorldAndCompatibility(t, connected, []record.CompatibilityPack{})
}

func publishReplayArtifactWithCompatibility(t *testing.T, compatibility []record.CompatibilityPack) (string, execution.Result) {
	return publishReplayArtifactWithWorldAndCompatibility(t, nil, compatibility)
}

func publishReplayArtifactWithWorldAndCompatibility(t *testing.T, connected *execution.Bundle, compatibility []record.CompatibilityPack) (string, execution.Result) {
	return publishReplayArtifactForTargetAndCompatibility(t, connected, compatibility, replayArtifactTarget{})
}

type replayArtifactTarget struct {
	Argv             []string
	Environment      []record.Environment
	OutcomeReason    string
	IOTranscript     []byte
	Choices          bool
	Simulation       bool
	ForcedSimulation bool
	// TargetPool publishes the artifact into a store that shares its target.
	TargetPool string
}

func publishReplayArtifactForTarget(t *testing.T, connected *execution.Bundle, replayTarget replayArtifactTarget) (string, execution.Result) {
	return publishReplayArtifactForTargetAndCompatibility(t, connected, []record.CompatibilityPack{}, replayTarget)
}

func publishReplayArtifactForTargetAndCompatibility(t *testing.T, connected *execution.Bundle, compatibility []record.CompatibilityPack, replayTarget replayArtifactTarget) (string, execution.Result) {
	t.Helper()
	targetPath, err := os.Executable()
	if err != nil {
		t.Fatal(err)
	}
	build, err := buildinfo.ReadFile(targetPath)
	if err != nil {
		t.Fatal(err)
	}
	targetBytes, err := os.ReadFile(targetPath)
	if err != nil {
		t.Fatal(err)
	}
	identity, err := target.ReadToolchainIdentity(toolchainRoot(t))
	if err != nil {
		t.Fatal(err)
	}
	stdout := replayOutput("recorded stdout")
	stderr := replayOutput("recorded stderr")
	ioTranscript := replayTarget.IOTranscript
	ioTranscriptSHA256 := sha256.Sum256(ioTranscript)
	ioTranscriptRecords, err := deterministicio.TranscriptRecordCount(ioTranscript)
	if err != nil {
		t.Fatal(err)
	}
	profile := deterministicio.Default()
	exitCode := record.Uint64String(2)
	targetArgv := replayTarget.Argv
	if len(targetArgv) == 0 {
		targetArgv = []string{"gomad3-target", "-test.run=none"}
	}
	environment := append([]record.Environment{
		{Name: "GOMADSEED", Value: "7"},
		{Name: "GOMAD3_IO_PROFILE", Value: profile.Name()},
		{Name: "TZ", Value: "UTC"},
	}, replayTarget.Environment...)
	sort.Slice(environment, func(i, j int) bool { return environment[i].Name < environment[j].Name })
	outcomeReason := replayTarget.OutcomeReason
	if outcomeReason == "" {
		outcomeReason = "nonzero_exit"
	}
	recordedWorld, payloads := record.NoneWorld()
	if connected != nil {
		recordedWorld = connected.Manifest
		payloads = connected.Payloads
	}
	input := artifact.ArtifactInput{
		Manifest: record.ExecutionRecord{
			SchemaVersion: record.SchemaVersion, ArtifactKind: record.ArtifactTargetFailure, CreatedAt: "2026-08-10T12:00:00Z", CampaignID: "replay-test",
			SelectionOrdinal: 0, Seed: 7, ReplayMode: record.ReplayExact,
			Runner:    record.Runner{RecordContract: record.RecordContract, RunnerBuild: "sha256:bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb", HostOS: runtime.GOOS, HostArch: runtime.GOARCH},
			Toolchain: record.Toolchain{GoVersion: identity.GoVersion, BuildKey: identity.BuildKey, TargetGOOS: identity.TargetGOOS, TargetGOARCH: identity.TargetGOARCH},
			Target: record.Target{
				Kind: "go-test", Source: "replay fixture", SHA256: record.HashBytes(targetBytes), Size: record.Uint64String(len(targetBytes)),
				Argv: targetArgv, BuildTags: []string{"gomad_fixture"}, Adapters: []record.TargetAdapter{}, Compatibility: compatibility, BuildInfo: projectTestBuildInfo(build),
			},
			IOProfile: record.IOProfile{
				Name: profile.Name(), ImplementationSHA256: record.SHA256(profile.ImplementationSHA256()), Inventory: string(profile.Inventory()), InventorySHA256: record.SHA256(profile.InventorySHA256()),
				Transcript: &record.IOTranscript{Schema: "gomad3.io-transcript/v1", SHA256: record.SHA256FromSum(ioTranscriptSHA256), Bytes: record.Uint64String(len(ioTranscript)), Records: record.Uint64String(ioTranscriptRecords)},
			},
			Environment: environment,
			Limits:      record.Limits{ExecutionTimeoutNanos: record.Uint64String(5 * time.Second), OverallTimeoutNanos: record.Uint64String(10 * time.Second), TerminateGraceNanos: record.Uint64String(100 * time.Millisecond), OutputBytes: 64, WorldTransitionBytes: 1 << 20, IOTranscriptBytes: 64 << 20},
			World:       recordedWorld,
			Outcome:     record.Outcome{Domain: "target", Reason: outcomeReason, Termination: "exit", ExitCode: &exitCode},
			Streams:     record.Streams{Stdout: replayStream(stdout), Stderr: replayStream(stderr)},
			Host:        record.Host{StartedAt: "2026-08-10T12:00:00Z", FinishedAt: "2026-08-10T12:00:01Z", ElapsedNanos: record.Uint64String(time.Second)},
		},
		TargetPath: targetPath, Stdout: stdout.Bytes, Stderr: stderr.Bytes, IOTranscript: ioTranscript, World: payloads,
	}
	var recordedChoices execution.ChoiceTrace
	if replayTarget.Choices {
		implementation, identityErr := choice.ImplementationIdentity(identity.BuildKey)
		if identityErr != nil {
			t.Fatal(identityErr)
		}
		first := sha256.Sum256([]byte("first choice alternative"))
		second := sha256.Sum256([]byte("second choice alternative"))
		decision, decisionErr := choice.CanonicalDecision(0, choice.KindRunnable, 17, false, [][sha256.Size]byte{first, second}, second, 0)
		if decisionErr != nil {
			t.Fatal(decisionErr)
		}
		choiceTrace, decodeErr := choice.BuildTrace([]choice.Record{decision.Record()}, choice.TerminalComplete)
		if decodeErr != nil {
			t.Fatal(decodeErr)
		}
		choicePayload := append([]byte(nil), choiceTrace.Bytes...)
		choiceLimit, limitErr := choice.TraceBytes(1)
		if limitErr != nil {
			t.Fatal(limitErr)
		}
		targetSHA256, targetErr := input.Manifest.Target.SHA256.Bytes()
		if targetErr != nil {
			t.Fatal(targetErr)
		}
		executionIdentity := choice.ExecutionIdentity{
			TargetSHA256: targetSHA256, ToolchainBuildKey: identity.BuildKey,
			GOOS: identity.TargetGOOS, GOARCH: identity.TargetGOARCH, ImplementationSHA256: implementation,
		}
		tape, tapeErr := choice.ProjectReplayPlan(choiceTrace, executionIdentity)
		if tapeErr != nil {
			t.Fatal(tapeErr)
		}
		input.Manifest.ChoiceProfile = &record.ChoiceProfile{
			Name: choice.Profile, ImplementationSHA256: record.SHA256FromSum(implementation),
			Trace: record.ChoiceTrace{
				Schema: "gomad3.choice-trace/v3", SHA256: record.SHA256FromSum(choiceTrace.SHA256), Bytes: record.Uint64String(len(choiceTrace.Bytes)),
				Records: 1, BranchingRecords: 1, TerminalState: "complete", Limit: record.Uint64String(choiceLimit),
				TapeSHA256: record.SHA256FromSum(tape.SHA256), Decisions: 1,
			},
		}
		input.Manifest.Limits.ChoiceTraceBytes = record.Uint64String(choiceLimit)
		input.Manifest.Environment = append(input.Manifest.Environment, record.Environment{Name: "GOMAD3_CHOICE_PROFILE", Value: choice.Profile})
		sort.Slice(input.Manifest.Environment, func(i, j int) bool { return input.Manifest.Environment[i].Name < input.Manifest.Environment[j].Name })
		input.ChoiceTrace = choicePayload
		recordedChoices = execution.ChoiceTrace{Profile: choice.Profile, ImplementationSHA256: implementation, Limit: choiceLimit, Trace: choiceTrace}
	}
	var recordedSimulationRecords [][]byte
	if replayTarget.Simulation {
		config := simulationengine.Config{
			ExecutionSHA256: record.HashBytes([]byte("replay simulation execution")), ControllerSHA256: simulationengine.ImplementationSHA256(), BaseSeed: 7,
			Parallel: 1, MaxExecutions: 1, MaxForcedDecisions: 1, MaxExplorationBytes: 1 << 20, MaxResultBytes: 1 << 20, FailureBudget: 1,
			Limits: simulationengine.DimensionLimits{Runtime: 1, Scenario: 1, Network: 1, Storage: 1, Fault: 1, Crash: 1},
		}
		state, stateErr := simulationengine.New(config)
		if stateErr != nil {
			t.Fatal(stateErr)
		}
		round, ok := state.NextRound()
		if !ok {
			t.Fatal("simulation replay root candidate is unavailable")
		}
		candidate := round.Candidates[0]
		var runtimeDecisions []simulationengine.Decision
		var explorationDecisions []simulationengine.Decision
		if replayTarget.ForcedSimulation {
			if !replayTarget.Choices {
				t.Fatal("forced simulation fixture requires choices")
			}
			targetSHA256, targetErr := input.Manifest.Target.SHA256.Bytes()
			if targetErr != nil {
				t.Fatal(targetErr)
			}
			implementation, implementationErr := choice.ImplementationIdentity(identity.BuildKey)
			if implementationErr != nil {
				t.Fatal(implementationErr)
			}
			executionIdentity := choice.ExecutionIdentity{
				TargetSHA256: targetSHA256, ToolchainBuildKey: identity.BuildKey, GOOS: identity.TargetGOOS,
				GOARCH: identity.TargetGOARCH, ImplementationSHA256: implementation,
			}
			exactTape, tapeErr := choice.ProjectReplayPlan(recordedChoices.Trace, executionIdentity)
			if tapeErr != nil {
				t.Fatal(tapeErr)
			}
			runtimeDecisions, tapeErr = simulationrecord.RuntimeDecisions(exactTape)
			if tapeErr != nil {
				t.Fatal(tapeErr)
			}
			prefix, prefixErr := choice.BuildForcedRankPrefix(exactTape, 0, runtimeDecisions[0].Selected)
			if prefixErr != nil {
				t.Fatal(prefixErr)
			}
			runtimeOverride, overrideErr := simulationengine.CanonicalForcedDecision(simulationengine.ForcedDecision{
				Dimension: simulationengine.DimensionRuntime, Ordinal: runtimeDecisions[0].Ordinal,
				SiteSHA256: runtimeDecisions[0].SiteSHA256, Alternatives: uint32(len(runtimeDecisions[0].Alternatives)),
				AlternativeSetSHA256: runtimeDecisions[0].AlternativeSetSHA256, Selected: runtimeDecisions[0].Selected,
				SelectedSHA256: runtimeDecisions[0].Alternatives[runtimeDecisions[0].Selected], Control: prefix.Bytes,
			})
			if overrideErr != nil {
				t.Fatal(overrideErr)
			}
			faultSite := record.HashBytes([]byte("fault site"))
			faultAlternatives := []record.SHA256{record.HashBytes([]byte("no fault")), record.HashBytes([]byte("drop"))}
			faultBaseline, decisionErr := simulationengine.CanonicalDecision(simulationengine.DimensionFault, 0, faultSite, faultAlternatives, 0)
			if decisionErr != nil {
				t.Fatal(decisionErr)
			}
			faultOverride, overrideErr := simulationengine.ForceDecision(faultBaseline, 1)
			if overrideErr != nil {
				t.Fatal(overrideErr)
			}
			candidate, overrideErr = simulationengine.CanonicalCandidate(config, []simulationengine.ForcedDecision{runtimeOverride, faultOverride}, "")
			if overrideErr != nil {
				t.Fatal(overrideErr)
			}
			faultObserved, decisionErr := simulationengine.CanonicalDecision(simulationengine.DimensionFault, 0, faultSite, faultAlternatives, 1)
			if decisionErr != nil {
				t.Fatal(decisionErr)
			}
			explorationDecisions = []simulationengine.Decision{faultObserved}
		}
		plan, planErr := simulationrecord.PlanForCandidate(config, candidate)
		if planErr != nil {
			t.Fatal(planErr)
		}
		record, recordErr := json.Marshal(struct {
			Schema               string                      `json:"schema"`
			Seed                 uint64                      `json:"seed"`
			SpecSHA256           record.SHA256               `json:"spec_sha256"`
			Outcome              string                      `json:"outcome"`
			FailureIdentity      record.SHA256               `json:"failure_identity"`
			ExplorationPlan      json.RawMessage             `json:"exploration_plan"`
			ExplorationDecisions []simulationengine.Decision `json:"exploration_decisions,omitempty"`
			Identity             record.SHA256               `json:"identity"`
		}{
			Schema: "gomad3.cluster-record/v7", Seed: 7, SpecSHA256: record.HashBytes([]byte("simulation spec")), Outcome: "oracle_failed",
			FailureIdentity: record.HashBytes([]byte("normalized replay failure")), ExplorationPlan: plan,
			ExplorationDecisions: explorationDecisions, Identity: record.HashBytes([]byte("simulation record")),
		})
		if recordErr != nil {
			t.Fatal(recordErr)
		}
		profile, profileErr := simulationrecord.ProjectArtifact(config, candidate, plan, record, runtimeDecisions, 1<<20)
		if profileErr != nil {
			t.Fatal(profileErr)
		}
		input.Manifest.SimulationProfile = &profile
		input.Simulation = &artifact.SimulationPayloads{Plan: plan, Record: record}
		recordedSimulationRecords = [][]byte{record}
	}
	published, err := artifact.PublishArtifact(artifact.Store{Root: t.TempDir(), TargetPool: replayTarget.TargetPool}, input)
	if err != nil {
		t.Fatal(err)
	}
	result := execution.Result{Termination: execution.TerminationExit, ExitCode: 2, GroupGone: true, Stdout: stdout, Stderr: stderr, IOTranscript: deterministicio.Transcript{SHA256: ioTranscriptSHA256, Records: ioTranscriptRecords, Complete: true}, ChoiceTrace: recordedChoices, SimulationRecords: recordedSimulationRecords}
	if connected != nil {
		initial, decodeErr := world.DecodeSnapshot(connected.Payloads.Initial)
		if decodeErr != nil {
			t.Fatal(decodeErr)
		}
		final, decodeErr := world.DecodeSnapshot(connected.Payloads.Final)
		if decodeErr != nil {
			t.Fatal(decodeErr)
		}
		result.WorldRecord, decodeErr = world.EncodeRecording(world.Recording{
			Initial: initial, Final: final,
			Terminal: world.Terminal{Kind: world.TerminalKind(connected.Manifest.Terminal.Kind), Detail: connected.Manifest.Terminal.Detail},
		})
		if decodeErr != nil {
			t.Fatal(decodeErr)
		}
	}
	return published.Path, result
}

