func (session *minimizationSession) prepareWorkspace() error {
	workDirectory, err := os.MkdirTemp("", "gomad3-minimize-")
	if err != nil {
		return fmt.Errorf("create minimization working directory: %w", err)
	}
	session.workDirectory = workDirectory
	if err := os.Chmod(workDirectory, 0o700); err != nil {
		return fmt.Errorf("make minimization working directory private: %w", err)
	}
	session.temporaryRoot = filepath.Join(workDirectory, "candidates")
	manifest := session.opened.Manifest()
	targetPath := filepath.Join(workDirectory, "target")
	if err := session.opened.CopyPayload(manifest.Target.File, targetPath, 0o500); err != nil {
		return fmt.Errorf("copy verified minimization target: %w", err)
	}
	if err := validateTargetBuildInfo(targetPath, manifest.Target.BuildInfo); err != nil {
		return err
	}
	session.prepared = preparedTargetFromArtifact(targetPath, manifest)
	if session.prepared.CapabilityMode != target.CapabilityModeClosure {
		capabilities, err := target.ReadCapabilityManifest(targetPath, target.ToolchainIdentity{
			GoVersion: manifest.Toolchain.GoVersion, BuildKey: manifest.Toolchain.BuildKey,
			TargetGOOS: manifest.Toolchain.TargetGOOS, TargetGOARCH: manifest.Toolchain.TargetGOARCH,
		})
		if err != nil {
			return fmt.Errorf("read minimized target capability manifest: %w", err)
		}
		session.prepared.CapabilityManifest = capabilities
	}
	runTimeout, err := duration(manifest.Limits.ExecutionTimeoutNanos)
	if err != nil {
		return err
	}
	overallTimeout, err := duration(manifest.Limits.OverallTimeoutNanos)
	if err != nil {
		return err
	}
	terminateGrace, err := duration(manifest.Limits.TerminateGraceNanos)
	if err != nil {
		return err
	}
	session.baseEnvironment = minimizationBaseEnvironment(manifest.Environment)
	session.mountLimits = readonlymount.DefaultLimits()
	if mounts := manifest.IOProfile.ReadOnlyMounts; mounts != nil {
		descriptor, readErr := session.opened.ReadPayload(mounts.File, uint64(mounts.Bytes))
		if readErr != nil {
			return fmt.Errorf("read minimized target mounts: %w", readErr)
		}
		mappings, limits, snapshot, readErr := readonlymount.DecodeCapturedInputs(replayCapturedInputs(*mounts), descriptor, func(name string, maximum uint64) ([]byte, error) {
			return session.opened.ReadPayload(name, maximum)
		})
		if readErr != nil {
			return fmt.Errorf("decode minimized target mounts: %w", readErr)
		}
		captured, encodeErr := readonlymount.EncodeCapturedInputs(mappings, limits, snapshot)
		if encodeErr != nil {
			return fmt.Errorf("encode minimized target mounts: %w", encodeErr)
		}
		session.mappings, session.mountLimits, session.mountSnapshot, session.mountArtifact = mappings, limits, &snapshot, &captured
	}
	session.campaign = CampaignSpec{
		ExecutionTimeout: runTimeout, OverallTimeout: overallTimeout, TerminateGrace: terminateGrace,
		OutputLimit: uint64(manifest.Limits.OutputBytes), WorldTransitionLimit: uint64(manifest.Limits.WorldTransitionBytes),
		ChoiceTraceLimit: uint64(manifest.Limits.ChoiceTraceBytes), RunnerBuild: manifest.Runner.RunnerBuild,
		IOROMountLimits: session.mountLimits, SupervisorCommand: append([]string(nil), session.config.SupervisorCommand...),
	}
	session.executor = session.dependencies.executor
	if session.executor == nil {
		if len(session.config.SupervisorCommand) == 0 {
			return errors.New("supervisor command is required")
		}
		session.executor = processExecutor{}
	}
	session.replayer = session.config.Replayer
	return nil
}

func preparedTargetFromArtifact(path string, manifest record.ExecutionRecord) target.Prepared {
	return target.Prepared{
		Path: path, Kind: target.Kind(manifest.Target.Kind), Source: manifest.Target.Source,
		SHA256: string(manifest.Target.SHA256), Size: uint64(manifest.Target.Size), Argv: append([]string(nil), manifest.Target.Argv...),
		BuildTags: append([]string(nil), manifest.Target.BuildTags...), Adapters: cloneAdapters(manifest.Target.Adapters),
		Compatibility: cloneCompatibility(manifest.Target.Compatibility), BuildInfo: manifest.Target.BuildInfo,
		GoVersion: manifest.Toolchain.GoVersion, BuildKey: manifest.Toolchain.BuildKey,
		TargetGOOS: manifest.Toolchain.TargetGOOS, TargetGOARCH: manifest.Toolchain.TargetGOARCH,
		CapabilityMode: target.CapabilityMode(manifest.Target.CapabilityMode),
	}
}

func replayWith(ctx context.Context, config ReplaySpec, dependencies executionDependencies) (result ReplayResult, retErr error) {
	opened, err := preflight(config)
	if err != nil {
		return ReplayResult{}, &ReplayPreflightError{Err: err}
	}
	defer func() {
		if closeErr := opened.Close(); closeErr != nil && retErr == nil {
			result = ReplayResult{}
			retErr = fmt.Errorf("close replay artifact: %w", closeErr)
		}
	}()
	manifest := opened.Manifest()
	if err := target.VerifyCompatibility(manifest.Target.Compatibility); err != nil {
		return ReplayResult{}, &ReplayPreflightError{Err: fmt.Errorf("verify replay compatibility: %w", err)}
	}
	if err := deterministicio.Default().VerifyAdapters(replayAdapters(manifest.Target.Adapters)); err != nil {
		return ReplayResult{}, &ReplayPreflightError{Err: fmt.Errorf("verify replay adapters: %w", err)}
	}
	result = ReplayResult{Artifact: opened.Snapshot(), Verified: true, Diagnostic: manifest.ReplayMode == record.ReplayDiagnostic, ChoiceReplayStatus: ChoiceReplayNone}
	choiceCapability, choiceUnavailable, err := choiceCapabilityForArtifact(opened)
	if err != nil {
		return ReplayResult{}, &ReplayPreflightError{Err: err}
	}
	if choiceUnavailable {
		result.ChoiceReplayStatus = ChoiceReplayUnavailable
		result.Divergence = "choice_profile.replay_unavailable"
		return result, nil
	}
	if choiceCapability != nil {
		result.ChoiceReplayStatus = ChoiceReplayAvailable
	}
	simulationReplay, err := simulationCapabilityForArtifact(opened)
	if err != nil {
		return ReplayResult{}, &ReplayPreflightError{Err: err}
	}
	if config.VerifyOnly {
		return result, nil
	}
	executor := dependencies.executor
	if executor == nil {
		if len(config.SupervisorCommand) == 0 {
			return ReplayResult{}, fmt.Errorf("supervisor command is required")
		}
		executor = replayProcessExecutor{}
	}
	workDirectory, err := os.MkdirTemp("", "gomad3-replay-")
	if err != nil {
		return ReplayResult{}, fmt.Errorf("create replay working directory: %w", err)
	}
	defer func() {
		if cleanupErr := os.RemoveAll(workDirectory); cleanupErr != nil && retErr == nil {
			result = ReplayResult{}
			retErr = fmt.Errorf("remove replay working directory: %w", cleanupErr)
		}
	}()
	if err := os.Chmod(workDirectory, 0o700); err != nil {
		return ReplayResult{}, fmt.Errorf("make replay working directory private: %w", err)
	}
	targetPath := filepath.Join(workDirectory, "target")
	if err := opened.CopyPayload(manifest.Target.File, targetPath, 0o500); err != nil {
		return ReplayResult{}, fmt.Errorf("copy verified replay target: %w", err)
	}
	if err := validateTargetBuildInfo(targetPath, manifest.Target.BuildInfo); err != nil {
		return ReplayResult{}, err
	}
	runTimeout, err := duration(manifest.Limits.ExecutionTimeoutNanos)
	if err != nil {
		return ReplayResult{}, err
	}
	terminateGrace, err := duration(manifest.Limits.TerminateGraceNanos)
	if err != nil {
		return ReplayResult{}, err
	}
	environment := replayEnvironment(manifest.Environment)
	var expectedWorldInitial []byte
	var worldReplayPlan []byte
	if manifest.World.Initial.Schema == "gomad3.world.snapshot/v1" {
		worldPayloads, readErr := readWorldPayloads(opened)
		if readErr != nil {
			return ReplayResult{}, fmt.Errorf("read replay World payloads: %w", readErr)
		}
		initial, final, validateErr := execution.Validate(manifest.World, worldPayloads)
		if validateErr != nil {
			return ReplayResult{}, fmt.Errorf("validate replay World plan: %w", validateErr)
		}
		expectedWorldInitial = worldPayloads.Initial
		worldReplayPlan, err = canonicaljson.CanonicalJSON(world.ReplayPlan{
			SchemaVersion: world.SchemaVersion,
			InitialDigest: initial.StateDigest,
			Transitions:   final.Transitions[len(initial.Transitions):],
			FinalDigest:   final.StateDigest,
		})
		if err != nil {
			return ReplayResult{}, fmt.Errorf("encode replay World plan: %w", err)
		}
	}
	var ioConfig []byte
	var ioTranscriptLimit uint64
	var expectedIOTranscript []byte
	var readOnlyMounts []readonlymount.Mapping
	var readOnlyMountLimits readonlymount.Limits
	readOnlyMountSnapshot := &readonlymount.Snapshot{}
	profile := deterministicio.Default()
	ioConfig, err = profile.BootstrapFrame(target.Prepared{SHA256: string(manifest.Target.SHA256), Argv: append([]string(nil), manifest.Target.Argv...)}, manifest.Runner.RunnerBuild, uint64(manifest.Seed))
	if err != nil {
		return ReplayResult{}, err
	}
	ioTranscriptLimit = uint64(manifest.Limits.IOTranscriptBytes)
	if manifest.IOProfile.Transcript == nil {
		if manifest.ReplayMode != record.ReplayDiagnostic {
			return ReplayResult{}, errors.New("recorded I/O profile has no complete transcript")
		}
		if choiceCapability != nil {
			return ReplayResult{}, errors.New("diagnostic replay without an I/O transcript cannot replay recorded choices")
		}
	}
	readOnlyMountLimits = readonlymount.DefaultLimits()
	if mounts := manifest.IOProfile.ReadOnlyMounts; mounts != nil {
		descriptor, readErr := opened.ReadPayload(mounts.File, uint64(mounts.Bytes))
		if readErr != nil {
			return ReplayResult{}, fmt.Errorf("read read-only mount descriptor: %w", readErr)
		}
		var snapshot readonlymount.Snapshot
		readOnlyMounts, readOnlyMountLimits, snapshot, readErr = readonlymount.DecodeCapturedInputs(replayCapturedInputs(*mounts), descriptor, func(name string, maximum uint64) ([]byte, error) {
			return opened.ReadPayload(name, maximum)
		})
		if readErr != nil {
			return ReplayResult{}, fmt.Errorf("decode read-only mount artifact: %w", readErr)
		}
		readOnlyMountSnapshot = &snapshot
	}
	if transcript := manifest.IOProfile.Transcript; transcript != nil {
		expectedIOTranscript, err = opened.ReadPayload(transcript.File, ioTranscriptLimit)
		if err != nil {
			return ReplayResult{}, fmt.Errorf("read expected I/O transcript: %w", err)
		}
	}
	ioCapability := &execution.IOCapability{
		Config:     ioConfig,
		Transcript: &execution.IOTranscriptCapability{Limit: ioTranscriptLimit, Replay: manifest.IOProfile.Transcript != nil, Expected: expectedIOTranscript},
		ReadOnlyMount: &execution.ReadOnlyMountCapability{
			Mappings: readOnlyMounts, Limits: readOnlyMountLimits, Replay: readOnlyMountSnapshot,
		},
	}
	request := execution.Spec{
		SupervisorCommand: append([]string(nil), config.SupervisorCommand...), Command: targetPath,
		BootstrapCommand: replayBootstrapCommand(config),
		Args:             append([]string(nil), manifest.Target.Argv[1:]...), Argv0: manifest.Target.Argv[0], Dir: workDirectory, Env: environment,
		ExecutionTimeout: runTimeout, TerminateGrace: terminateGrace, OutputLimit: uint64(manifest.Limits.OutputBytes),
		World: execution.WorldCapability{
			RecordLimit: world.MaximumRecordingBytes, TransitionLimit: uint64(manifest.Limits.WorldTransitionBytes),
			Seed: uint64(manifest.Seed), ExpectedInitial: expectedWorldInitial, ReplayPlan: worldReplayPlan,
		},
		IO: ioCapability, Choice: choiceCapability,
	}
	request.Simulation = simulationReplay.capability
	if request.Simulation == nil {
		if _, ok := executor.(replayProcessExecutor); ok {
			request.Simulation = &execution.SimulationCapability{Role: execution.SimulationRoleCoordinator}
		}
	}
	observed, err := executor.Run(ctx, request)
	if config.ObservedDir != "" {
		if dumpErr := dumpObservedStreams(config.ObservedDir, observed); dumpErr != nil {
			return ReplayResult{}, dumpErr
		}
	}
	if err != nil {
		if divergence, controlled := onlyChoiceReplayDivergence(err); controlled {
			result.ChoiceReplayStatus = ChoiceReplayDiverged
			result.Divergence = fmt.Sprintf("choice_profile.divergence.ordinal[%d].%s", divergence.Divergence.Ordinal, choice.DivergenceReasonName(divergence.Divergence.Reason))
			return result, nil
		}
		return ReplayResult{}, fmt.Errorf("execute replay target: %w", err)
	}
	var observedWorld *execution.Bundle
	if len(observed.WorldRecord) != 0 {
		recording, worldErr := world.DecodeRecording(observed.WorldRecord)
		if worldErr != nil {
			return ReplayResult{}, fmt.Errorf("decode replay World record: %w", worldErr)
		}
		if recording.Final.Replay.Expected != 0 && recording.Final.Replay.Cursor != recording.Final.Replay.Expected && recording.Terminal.Kind != world.TerminalReplayDivergence {
			return ReplayResult{}, errors.New("validate replay World record: final World replay is incomplete")
		}
		recording.Initial.Replay = world.ReplayProgress{}
		recording.Final.Replay = world.ReplayProgress{}
		bundle, worldErr := execution.ComposeRecording(recording, uint64(manifest.Limits.WorldTransitionBytes))
		if worldErr != nil {
			return ReplayResult{}, fmt.Errorf("validate replay World record: %w", worldErr)
		}
		observedWorld = &bundle
	}
	result.Divergence = simulationReplay.divergence(manifest, observed)
	if result.Divergence == "" {
		result.Divergence = replayDivergence(manifest, observed, observedWorld)
	}
	result.Match = result.Divergence == ""
	if choiceCapability != nil {
		if choiceTraceDivergence(manifest, observed) == "" {
			result.ChoiceReplayStatus = ChoiceReplayExact
		} else {
			result.ChoiceReplayStatus = ChoiceReplayDiverged
		}
	}
	return result, nil
}

type simulationArtifactReplay struct {
	capability     *execution.SimulationCapability
	expectedRecord []byte
}

func Resume(ctx context.Context, spec ResumeSpec) (CampaignResult, error) {
	return resumeWith(ctx, spec, executionDependencies{})
}

func resumeWith(ctx context.Context, spec ResumeSpec, dependencies executionDependencies) (CampaignResult, error) {
	return exploreWith(ctx, CampaignSpec{
		ResumeCampaign: spec.CampaignPath, RunnerBuild: spec.RunnerBuild, GuideRegressionOverride: spec.GuideRegression,
		Target:            target.Spec{ToolchainRoot: spec.ToolchainRoot},
		SupervisorCommand: append([]string(nil), spec.SupervisorCommand...), CoordinatorCommand: append([]string(nil), spec.CoordinatorCommand...),
		Progress: spec.Progress, ProgressInterval: spec.ProgressInterval, Replayer: spec.Replayer,
	}, dependencies)
}

func resumeConfiguration(request campaignRequest, plan campaign.CampaignPlan) (CampaignSpec, SeedSelection, []record.Environment, []readonlymount.Mapping, target.Prepared, error) {
	if plan.RunnerBuild != request.RunnerBuild {
		return CampaignSpec{}, SeedSelection{}, nil, nil, target.Prepared{}, fmt.Errorf("recorded Runner build identity %s does not match this Runner %s", plan.RunnerBuild, request.RunnerBuild)
	}
	profile := deterministicio.Default()
	if !profile.Matches(plan.IOProfile) {
		return CampaignSpec{}, SeedSelection{}, nil, nil, target.Prepared{}, fmt.Errorf("recorded I/O profile identity does not match this Runner")
	}
	if request.GuideRegressionOverride != nil && (plan.Guidance == nil || *request.GuideRegressionOverride != plan.Guidance.Regression) || request.GuideRegression && (plan.Guidance == nil || !plan.Guidance.Regression) || request.Guide && (plan.Guidance == nil || request.GuideRegression != plan.Guidance.Regression) {
		return CampaignSpec{}, SeedSelection{}, nil, nil, target.Prepared{}, errors.New("resume guidance regression mode does not match campaign plan")
	}
	selection, err := parseCampaignSelection(plan.Selection, uint64(plan.SelectionCount))
	if err != nil || selection.Count() != uint64(plan.SelectionCount) {
		return CampaignSpec{}, SeedSelection{}, nil, nil, target.Prepared{}, fmt.Errorf("recorded seed selection is invalid: %w", err)
	}
	mountLimits, err := readonlymount.DecodeLimits(deterministicCapturedInputLimits(plan.IOROMountLimits))
	if err != nil {
		return CampaignSpec{}, SeedSelection{}, nil, nil, target.Prepared{}, err
	}
	mounts, err := readonlymount.ParseMappings(plan.IOROMounts, "")
	if err != nil {
		return CampaignSpec{}, SeedSelection{}, nil, nil, target.Prepared{}, err
	}
	prepared := target.Prepared{
		Path: filepath.Join(request.ResumeCampaign, filepath.FromSlash(plan.Prepared.Path)), Kind: target.Kind(plan.Prepared.Target.Kind), Source: plan.Prepared.Target.Source,
		SHA256: string(plan.Prepared.Target.SHA256), Size: uint64(plan.Prepared.Target.Size), Argv: append([]string(nil), plan.Prepared.Target.Argv...),
		BuildTags: append([]string(nil), plan.Prepared.Target.BuildTags...), Adapters: cloneAdapters(plan.Prepared.Target.Adapters), Compatibility: cloneCompatibility(plan.Prepared.Target.Compatibility), BuildInfo: cloneBuildInfo(plan.Prepared.Target.BuildInfo),
		GoVersion: plan.Toolchain.GoVersion, BuildKey: plan.Toolchain.BuildKey, TargetGOOS: plan.Toolchain.TargetGOOS, TargetGOARCH: plan.Toolchain.TargetGOARCH,
		CapabilityMode: target.CapabilityMode(plan.Prepared.Target.CapabilityMode), CapabilityManifest: target.CapabilityManifestFromRecord(plan.Prepared.Target.CapabilityManifest),
	}
	if err := prepared.Verify(); err != nil {
		return CampaignSpec{}, SeedSelection{}, nil, nil, target.Prepared{}, err
	}
	if err := deterministicio.Default().VerifyAdapters(deterministicAdapters(prepared.Adapters)); err != nil {
		return CampaignSpec{}, SeedSelection{}, nil, nil, target.Prepared{}, fmt.Errorf("verify recorded adapters: %w", err)
	}
	if request.executor == nil {
		identity, err := target.ReadToolchainIdentity(request.Target.ToolchainRoot)
		if err != nil {
			return CampaignSpec{}, SeedSelection{}, nil, nil, target.Prepared{}, err
		}
		if identity.GoVersion != plan.Toolchain.GoVersion || identity.BuildKey != plan.Toolchain.BuildKey || identity.TargetGOOS != plan.Toolchain.TargetGOOS || identity.TargetGOARCH != plan.Toolchain.TargetGOARCH {
			return CampaignSpec{}, SeedSelection{}, nil, nil, target.Prepared{}, fmt.Errorf("recorded toolchain identity does not match the pinned toolchain")
		}
	}
	config := CampaignSpec{
		ResumeCampaign: request.ResumeCampaign, PlanSHA256: plan.PlanSHA256, Shard: runnerCampaignShard(plan.Shard),
		Strategy: Strategy(plan.Strategy), Seeds: plan.Selection, Parallel: int(plan.Parallel), ExecutionTimeout: time.Duration(plan.ExecutionTimeoutNanos), OverallTimeout: time.Duration(plan.OverallTimeoutNanos), TerminateGrace: time.Duration(plan.TerminateGraceNanos),
		OnFailure: FailurePolicy(plan.OnFailure), FailureBudget: uint64(plan.FailureBudget), OutputLimit: uint64(plan.OutputBytes), WorldTransitionLimit: uint64(plan.WorldTransitionBytes),
		MaxExecutions: uint64(plan.MaxExecutions), MaxChoiceDepth: uint64(plan.MaxChoiceDepth), ChoiceStartOrdinal: uint64(plan.ChoiceStartOrdinal), MaxForcedDecisions: uint64(plan.MaxForcedDecisions),
		MaxExplorationBytes: uint64(plan.MaxExplorationBytes), MaxExplorationResultBytes: uint64(plan.MaxExplorationResultBytes), SimulationDimensionLimits: SimulationDimensionLimits(plan.SimulationDimensionLimits),
		Artifacts: filepath.Dir(filepath.Dir(request.ResumeCampaign)), IOROMounts: append([]string(nil), plan.IOROMounts...), IOROMountLimits: mountLimits,
		Target: target.Spec{ToolchainRoot: request.Target.ToolchainRoot}, SupervisorCommand: append([]string(nil), request.SupervisorCommand...), RunnerBuild: request.RunnerBuild,
		Coverage: CoverageMode(plan.Coverage), RequiredSemanticProbes: append([]string(nil), plan.RequiredSemanticProbes...),
		KeepSuccesses: KeepSuccesses(plan.KeepSuccesses), SuccessArtifactLimit: uint64(plan.SuccessArtifactLimit), SuccessBytesLimit: uint64(plan.SuccessBytesLimit),
		Progress: request.Progress, ProgressInterval: request.ProgressInterval, Replayer: request.Replayer,
	}
	if plan.ChoiceProfile != nil {
		config.ChoiceTraceLimit = uint64(plan.ChoiceProfile.Limit)
	}
	config.IOTranscriptLimit = uint64(plan.IOTranscriptBytes)
	for _, entry := range plan.Environment {
		if entry.Name == choice.DiagnosticProfileEnvironment {
			if entry.Value != choice.DiagnosticProfile || config.ChoiceTraceLimit == 0 || NormalizeStrategy(config.Strategy) != StrategySeed {
				return CampaignSpec{}, SeedSelection{}, nil, nil, target.Prepared{}, errors.New("recorded diagnostic profile is invalid")
			}
			config.Diagnostics = true
		}
		if entry.Name == record.ClockTickEnvironment {
			config.ClockTick = entry.Value
		}
	}
	if plan.Guidance != nil {
		config.Guide = true
		config.GuideRegression = plan.Guidance.Regression
		config.guidancePlan = plan.Guidance
		config.Corpus = plan.Guidance.Corpus
		config.GuideSnapshotSHA256 = plan.Guidance.SnapshotSHA256
	}
	if plan.Artifacts != nil {
		config.failureArtifactLimit = uint64(plan.Artifacts.FailureArtifacts)
		config.failureBytesLimit = uint64(plan.Artifacts.FailureBytes)
	}
	return config, selection, append([]record.Environment(nil), plan.Environment...), mounts, prepared, nil
}

func restoreResumeSummary(batchPath string, selection SeedSelection, runs []campaign.ExecutionRecord) (resumeSummaryState, error) {
	state := resumeSummaryState{
		summary:  CampaignResult{CampaignPath: batchPath, SelectionCount: selection.Count(), Attempted: uint64(len(runs))},
		distinct: make(map[record.SHA256]string), probes: make(map[string]struct{}), choiceFeatures: make(map[string]struct{}), completed: make(map[uint64]struct{}, len(runs)),
	}
	for index, run := range runs {
		ordinal := uint64(run.SelectionOrdinal)
		seed, ok := selection.SeedAt(ordinal)
		if run.Strategy == string(StrategyChoiceExploration) || run.Strategy == string(StrategySimulationExploration) {
			seed, ok = selection.SeedAt(0)
		}
		if !ok || seed != uint64(run.Seed) {
			return resumeSummaryState{}, fmt.Errorf("resumable execution %d seed does not match selection ordinal", index+1)
		}
		state.completed[ordinal] = struct{}{}
		for _, probe := range run.SemanticProbes {
			state.probes[probe] = struct{}{}
		}
		for _, feature := range run.ChoiceFeatures {
			state.choiceFeatures[feature] = struct{}{}
		}
		switch run.Domain {
		case "success":
			state.summary.Succeeded++
			if run.SuccessArtifact != nil {
				path := filepath.Join(batchPath, filepath.FromSlash(*run.SuccessArtifact))
				state.summary.RetainedSuccesses++
				state.summary.RetainedSuccessBytes += uint64(*run.SuccessArtifactBytes)
				state.summary.SuccessArtifacts = append(state.summary.SuccessArtifacts, path)
			}
		case "target", "watchdog":
			state.summary.Failures++
			if run.Domain == "watchdog" {
				state.summary.Watchdogs++
			}
			if run.Reason == "world_replay_divergence" {
				state.summary.ReplayDivergences++
			}
			if _, found := state.distinct[*run.FailureSignature]; !found {
				path := filepath.Join(batchPath, filepath.FromSlash(*run.Artifact))
				opened, err := artifact.OpenArtifact(path)
				if err != nil {
					return resumeSummaryState{}, fmt.Errorf("open resumable failure artifact %d: %w", index+1, err)
				}
				if opened.StoredBytes() > ^uint64(0)-state.failureArtifactBytes {
					return resumeSummaryState{}, errors.Join(errors.New("resumable failure artifact bytes overflow"), opened.Close())
				}
				state.failureArtifactBytes += opened.StoredBytes()
				if err := opened.Close(); err != nil {
					return resumeSummaryState{}, fmt.Errorf("close resumable failure artifact %d: %w", index+1, err)
				}
				state.distinct[*run.FailureSignature] = path
				state.summary.Artifacts = append(state.summary.Artifacts, path)
			}
		case "runner":
			if run.Strategy != string(StrategyChoiceExploration) || run.Reason != "replay_divergence" || run.Divergence == nil {
				return resumeSummaryState{}, fmt.Errorf("resumable execution %d runner result cannot be reused", index+1)
			}
			state.summary.Failures++
			state.summary.ReplayDivergences++
		default:
			return resumeSummaryState{}, fmt.Errorf("resumable execution %d domain %q cannot be reused", index+1, run.Domain)
		}
	}
	state.summary.DistinctFailures = uint64(len(state.distinct))
	state.summary.failureArtifactBytes = state.failureArtifactBytes
	return state, nil
}
